create table public.feed_reactions(post_id uuid not null references public.feed_posts(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,emoji text not null check(emoji=any(array['❤️','😍','😂','🥹','🔥','👏','💕','😮'])),created_at timestamptz not null default now(),primary key(post_id,user_id));
create table public.feed_comments(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.feed_posts(id)on delete cascade,user_id uuid not null references public.profiles(id)on delete cascade,body text not null check(char_length(btrim(body))between 1 and 1000),created_at timestamptz not null default now());
create index feed_comments_time on public.feed_comments(post_id,created_at);
alter table public.feed_reactions enable row level security;alter table public.feed_comments enable row level security;
create policy feed_reaction_read on public.feed_reactions for select to authenticated using(exists(select from public.feed_posts p where p.id=post_id));
create policy feed_comment_read on public.feed_comments for select to authenticated using(exists(select from public.feed_posts p where p.id=post_id));
grant select on public.feed_reactions,public.feed_comments to authenticated;grant all on public.feed_reactions,public.feed_comments to service_role;
create function public.feed_react(p_id uuid,p_emoji text)returns void language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();p public.feed_posts;begin
 select * into p from public.feed_posts where id=p_id for update;if uid is null or p.id is null or uid not in(p.owner_id,p.partner_id)or public.friend_id(p.owner_id)is distinct from p.partner_id then raise insufficient_privilege;end if;
 if p_emoji is null or exists(select from public.feed_reactions where post_id=p_id and user_id=uid and emoji=p_emoji)then delete from public.feed_reactions where post_id=p_id and user_id=uid;else insert into public.feed_reactions(post_id,user_id,emoji)values(p_id,uid,p_emoji)on conflict(post_id,user_id)do update set emoji=excluded.emoji,created_at=now();end if;end$$;
create function public.feed_comment(p_id uuid,p_body text,p_comment uuid)returns uuid language plpgsql security definer set search_path=public as $$declare uid uuid:=auth.uid();p public.feed_posts;begin
 select * into p from public.feed_posts where id=p_id for update;if uid is null or p.id is null or uid not in(p.owner_id,p.partner_id)or public.friend_id(p.owner_id)is distinct from p.partner_id then raise insufficient_privilege;end if;
 if char_length(btrim(coalesce(p_body,'')))not between 1 and 1000 then raise exception 'Write a comment up to 1000 characters';end if;
 insert into public.feed_comments(id,post_id,user_id,body)values(p_comment,p_id,uid,btrim(p_body))on conflict(id)do nothing;return p_comment;end$$;
create function public.feed_comment_delete(p_id uuid)returns void language plpgsql security definer set search_path=public as $$begin if auth.uid()is null then raise insufficient_privilege;end if;delete from public.feed_comments where id=p_id and user_id=auth.uid();end$$;
revoke all on function public.feed_react(uuid,text),public.feed_comment(uuid,text,uuid),public.feed_comment_delete(uuid)from public,anon;grant execute on function public.feed_react(uuid,text),public.feed_comment(uuid,text,uuid),public.feed_comment_delete(uuid)to authenticated;
